import{W as e,_t as t,it as n,rt as r}from"./chunks/framework.CMcVP7ho.js";var i=JSON.parse(`{"title":"Dependency and artifact audit","description":"","frontmatter":{},"headers":[],"relativePath":"dependency-audit.md","filePath":"dependency-audit.md","lastUpdated":1788143512000}`),a={name:`dependency-audit.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="dependency-and-artifact-audit" tabindex="-1">Dependency and artifact audit <a class="header-anchor" href="#dependency-and-artifact-audit" aria-label="Permalink to “Dependency and artifact audit”">​</a></h1><p>The release policy keeps every duplicated Rust dependency and local crate override explicit. CI also records size budgets for the three executable delivery surfaces. The machine-readable source of truth is <a href="../audits/release-policy.json"><code>audits/release-policy.json</code></a>.</p><h2 id="duplicate-dependency-decisions" tabindex="-1">Duplicate dependency decisions <a class="header-anchor" href="#duplicate-dependency-decisions" aria-label="Permalink to “Duplicate dependency decisions”">​</a></h2><p>The 2026-08-30 dependency upgrade removed the duplicated Brotli and thiserror major versions. Four reviewed groups remain:</p><table tabindex="0"><thead><tr><th>Dependency</th><th>Versions</th><th>Decision</th><th>Replacement condition</th></tr></thead><tbody><tr><td><code>hashbrown</code></td><td>0.15.5 / 0.17.1</td><td>Retain</td><td>Remove v0.15 when the <code>wasmi</code>/<code>string-interner</code> and <code>indexmap</code> chains align.</td></tr><tr><td><code>miniz_oxide</code></td><td>0.8.9 / 0.9.1</td><td>Retain</td><td>Wait for the <code>backtrace</code> and <code>flate2</code> chains to align.</td></tr><tr><td><code>syn</code></td><td>2.0.119 / 3.0.4</td><td>Retain</td><td>Wait for the remaining procedural-macro crates to adopt syn 3.</td></tr><tr><td><code>unicode-width</code></td><td>0.1.14 / 0.2.2</td><td>Retain</td><td>Wait for the <code>miette</code>/<code>textwrap</code> chain to unify without changing diagnostics.</td></tr></tbody></table><p>The owner for every decision is the fontmin-rs maintainers. The dependency gate fails if a new duplicate appears, a recorded version changes, or a duplicate disappears without its retained decision being removed.</p><h2 id="vendored-patch-decisions" tabindex="-1">Vendored patch decisions <a class="header-anchor" href="#vendored-patch-decisions" aria-label="Permalink to “Vendored patch decisions”">​</a></h2><table tabindex="0"><thead><tr><th>Crate</th><th>Upstream</th><th>Decision and exit</th></tr></thead><tbody><tr><td><code>allsorts</code> 0.17.0</td><td><a href="https://github.com/yeslogic/allsorts" target="_blank" rel="noreferrer">yeslogic/allsorts</a></td><td>Retain the CFF INDEX and <code>endchar</code> corrections until an upstream release contains equivalent behavior and the permanent regression corpus passes.</td></tr><tr><td><code>oxifont-core</code> 0.2.2</td><td><a href="https://github.com/cool-japan/oxifont" target="_blank" rel="noreferrer">cool-japan/oxifont</a></td><td>Retain the MSRV metadata-only patch until upstream declares Rust 1.88 support, or this project raises its MSRV in a SemVer-minor release.</td></tr><tr><td><code>oxifont-subset</code> 0.2.2</td><td><a href="https://github.com/cool-japan/oxifont" target="_blank" rel="noreferrer">cool-japan/oxifont</a></td><td>Retain the manifest patch until upstream supports Rust 1.88 and removes its unused production parser dependencies, or the audited exit conditions are met.</td></tr><tr><td><code>safer-bytes</code> 0.2.0</td><td><a href="https://github.com/danieleades/safer-bytes" target="_blank" rel="noreferrer">danieleades/safer-bytes</a></td><td>Retain the stable-Rust compatibility copy until the selected WOFF2 decoder no longer requires it.</td></tr><tr><td><code>woff2-patched</code> 0.4.0</td><td><a href="https://github.com/zimond/woff2-rs" target="_blank" rel="noreferrer">zimond/woff2-rs</a></td><td>Retain explicit coordinate wrapping until an upstream release or owned decoder passes every WOFF2 regression.</td></tr></tbody></table><p>Each override has patch notes beside its source. The audit verifies that the root Cargo patch, notes, owner, upstream, decision, and removal condition remain present together. The two oxifont copies retain the published 0.2.2 Rust sources. <code>oxifont-core</code> only lowers its manifest-declared Rust version from 1.89 to 1.88. <code>oxifont-subset</code> also removes unused production dependencies on <code>oxifont-parser</code> and the unmaintained <code>ttf-parser</code>; neither is referenced by its <code>src/</code> tree. The complete workspace is compiled on Rust 1.98 in CI. The MSRV increase reaches the recorded exit condition for the <code>oxifont-core</code> metadata patch, so removing that override requires a dedicated dependency-graph review.</p><h2 id="release-artifact-budgets" tabindex="-1">Release artifact budgets <a class="header-anchor" href="#release-artifact-budgets" aria-label="Permalink to “Release artifact budgets”">​</a></h2><p>Release builds use thin LTO, one codegen unit, and stripped symbols. The budgets are intentionally portable across the supported CI platforms:</p><table tabindex="0"><thead><tr><th>Artifact</th><th style="text-align:right;">Budget</th></tr></thead><tbody><tr><td>Rust CLI</td><td style="text-align:right;">8 MiB</td></tr><tr><td>Native Node binding</td><td style="text-align:right;">8 MiB</td></tr><tr><td>Browser WASM binary</td><td style="text-align:right;">5 MiB</td></tr></tbody></table><p>On macOS arm64 with the current feature set, the local measurements were 7,139,040 bytes for the CLI, 5,678,928 bytes for the native binding, and 4,731,426 bytes for WASM. The WASM budget includes headroom for the browser runtime&#39;s variable-font reduction and source-bound subset-plan support. CI writes its platform measurements to <code>audits/artifact-current.json</code> and uploads the report even alongside the performance reports.</p><p>Run the policy-only check with:</p><div class="language-shell line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> audit:dependencies</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Build and measure all release surfaces with:</p><div class="language-shell line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> audit:artifacts</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Artifact budget failures persist the complete report before exiting, so the responsible delivery surface and measured bytes remain available for review.</p>`,18)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};